import RNA, random, multiprocessing as mp, time
target='.....((((.(...(.((((.(.((((.((.((((.((.(((....))).).)))))).).))))....).)))).)...).))))....................'
n=len(target)
seed='ACACCUCAAGGAAACCUAUGUCCUCUCCCUAGGCUUGUGCAUUAUUGUGGGUCAGCCCCGCGAGAACCCGUCAUAUGAAACGUUGAACUCUCAAACAAUUUUCUGU'
def worker(sidx):
    random.seed(sidx)
    for it in range(300):
        if it%3==0 and sidx<30:
            # perturb seed
            c=list(seed)
            for _ in range(random.randint(1,5)):
                c[random.randrange(n)]=random.choice('ACGU')
            start=''.join(c)
        else:
            start=''.join(random.choice('ACGU') for _ in range(n))
        seq, d = RNA.inverse_fold(start, target)
        if d == 0 and RNA.fold_compound(seq).mfe()[0] == target:
            return seq
    return None
if __name__=='__main__':
    with mp.Pool(64) as p:
        results=[]
        for r in p.imap_unordered(worker, range(512)):
            results.append(r)
            if r: 
                print('SOLVED', r, flush=True)
                p.terminate(); break
        else:
            print('NONE', flush=True)
EOF
